// Runs inside the runtime after `npm install is-odd@3.0.1` has written node_modules.
//
// `is-odd` is small on purpose: it is pure JavaScript, has a dependency (is-number), and is published with an `exports` map, so
// requiring it exercises resolution rather than a bundler. Both facts the fixture asserts come from the package itself, not from
// our own arithmetic: 3 is odd and 4 is not, and a wrong answer from the dependency would be a real failure rather than a typo.
import isOdd from "is-odd";

const three = isOdd(3);
const four = isOdd(4);
console.log(`is-odd(3)=${three} is-odd(4)=${four}`);

if (three !== true || four !== false) {
  console.error("is-odd gave the wrong answer, so resolution found something other than the published package");
  process.exit(1);
}

// The assertion looks for "true" in stdout, and this line is where it comes from: a boolean the package computed.
console.log("resolved-and-correct: true");
